// The built-in manifest is generated by custom/scripts/package-subs-models.ps1
// (src/ModelManifestData.inc); tests and future model sets pass their own.
#pragma once

#include <QByteArray>
#include <QList>
#include <QString>
#include <QUrl>

namespace crispplay::subs {

struct ModelFileEntry {
    QString path;        // relative to the model root, '/' separated ("ppocr-rec/PP-OCRv6_rec_small.onnx")
    qint64 size = 0;     // bytes
    QByteArray sha256;   // lower-case hex
};

struct ModelManifest {
    QString assetName;      // file name of the release asset (also the temp file name)
    qint64 zipSize = 0;     // exact size of the asset; also the download size cap
    QByteArray zipSha256;   // lower-case hex
    QList<ModelFileEntry> files;
};

// The manifest compiled into the binary (crispplay-subs-models-v1.zip).
const ModelManifest& builtInModelManifest();

struct ModelStoreOptions {
    QUrl url;                       // https; redirects only to the same host or GitHub's release CDN
    ModelManifest manifest;
    // Tests only: also accept http:// on 127.0.0.1 / localhost / ::1 (and redirects on that host).
    bool allowLoopbackHttp = false;
    int stallTimeoutMs = 30000;     // no byte for this long -> the download fails (and can be resumed)
};

// branding::subsModelsUrl() + builtInModelManifest().
ModelStoreOptions defaultModelStoreOptions();

} // namespace crispplay::subs
